"""Local inference API. Load only artifacts generated by trusted code."""

import hashlib
import io
import os
from contextlib import asynccontextmanager
from pathlib import Path
from typing import Annotated

import joblib
from fastapi import FastAPI
from pydantic import BaseModel, ConfigDict, Field, StringConstraints

Text = Annotated[str, StringConstraints(strict=True, strip_whitespace=True, min_length=1, max_length=10000)]


class PredictRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    texts: list[Text] = Field(min_length=1, max_length=32)


class Prediction(BaseModel):
    label_id: int
    label: str


class PredictResponse(BaseModel):
    model_sha256: str
    predictions: list[Prediction]


def create_app(model_path=None):
    path = Path(model_path or os.environ.get("TERRYMOK_MODEL_PATH", "artifacts/selected-model.joblib"))

    @asynccontextmanager
    async def lifespan(app):
        model_bytes = path.read_bytes()
        artifact = joblib.load(io.BytesIO(model_bytes))
        labels = artifact["labels"]
        model = artifact["pipeline"]
        if (not labels or any(not isinstance(label, str) for label in labels)
                or len(set(labels)) != len(labels)
                or list(model.classes_) != list(range(len(labels)))):
            raise ValueError("Model class mapping is invalid")
        app.state.model = model
        app.state.labels = labels
        app.state.digest = hashlib.sha256(model_bytes).hexdigest()
        yield

    app = FastAPI(title="TerryMok inference", version="0.1.0", lifespan=lifespan)

    @app.get("/health")
    def health():
        return {"status": "ready", "model_sha256": app.state.digest,
                "labels": app.state.labels}

    @app.post("/predict", response_model=PredictResponse)
    def predict(request: PredictRequest):
        ids = app.state.model.predict(request.texts)
        return {"model_sha256": app.state.digest, "predictions": [
            {"label_id": int(value), "label": app.state.labels[int(value)]} for value in ids
        ]}

    return app
